package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.config.CatalogDayAnalysisProofGraph;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.PlatformTransactionManager;

/** Actual registered source, permanent day allocation and native INPUT; model transport is fictional. */
class CatalogDayAnalysisPreparationCycleTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisProofGraphTest helper(){return new CatalogDayAnalysisProofGraphTest(){@Override boolean mysql(){return CatalogDayAnalysisPreparationCycleTest.this.mysql();}};}
    CatalogDayAnalysisPreparationCycle cycle(CatalogDayFullNativeIntegrationTest.Fixture f,CatalogDayAnalysisProofGraph graph,Clock clock,BooleanSupplier gate){return new CatalogDayAnalysisPreparationCycle(new JdbcCatalogAnalysisDays(f.f.source),graph.evidence(),graph.eligibility(),graph.reservations(),graph.allocation(),graph.prepared(),graph.preparation(),f.f.tx,clock,gate,f.f.category);}
    @Test void FourActualCategoriesFreezeExactlyOneOriginalEntityAndRestartWithoutMoreGenerationsOrCalls(){for(String category:List.of("agent","skill","workflow","model")){var helper=helper();var outer=helper.outer();var f=outer.new NewFixture();f.terminal(category);f.completeSource();var clock=Clock.fixed(outer.completed.plusSeconds(120),ZoneOffset.UTC);var graph=helper.graph(f,clock,helper.settings(),()->true);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.PREPARED,cycle(f,graph,clock,()->true).run(()->true));assertEquals(1,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.SETTLED,cycle(f,helper.graph(f,clock,helper.settings(),()->false),clock,()->false).run(()->true));assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,f.f.sends);}}
    @Test void OriginalAllocationSurvivesInputFailureAndCycleRestartResumesThatSameGeneration(){var helper=helper();var outer=helper.outer();var f=outer.new NewFixture();f.terminal("skill");f.completeSource();var clock=Clock.fixed(outer.completed.plusSeconds(120),ZoneOffset.UTC);var graph=helper.graph(f,clock,helper.settings(),()->true);f.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_day_cycle_failure CHECK(target_type IS NULL OR target_type<>'generation_prepare' OR operator_id<>'catalog-analysis-coordinator')");assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.RECOVERY_REQUIRED,cycle(f,graph,clock,()->true).run(()->true));assertEquals(1,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));f.f.jdbc.execute(mysql()?"ALTER TABLE jobs DROP CHECK fictional_day_cycle_failure":"ALTER TABLE jobs DROP CONSTRAINT fictional_day_cycle_failure");assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.PREPARED,cycle(f,helper.graph(f,clock,helper.settings(),()->true),clock,()->true).run(()->true));assertEquals(1,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));assertEquals(2,f.f.sends);}
    @Test void WholeCohortMissingSourceWaitsAndGatePreventsAllocationUntilDeadlineAndResume(){var helper=helper();var outer=helper.outer();var f=outer.new NewFixture();f.secondEnabled=true;f.terminal("agent");f.completeSource();var early=Clock.fixed(outer.completed.plusSeconds(120),ZoneOffset.UTC);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.PENDING,cycle(f,helper.graph(f,early,helper.settings(),()->true),early,()->true).run(()->true));assertEquals(0,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));var clock=Clock.fixed(SourceDedupBarrier.deadline(outer.day),ZoneOffset.UTC);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.GATED,cycle(f,helper.graph(f,clock,helper.settings(),()->false),clock,()->false).run(()->true));assertEquals(0,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.PREPARED,cycle(f,helper.graph(f,clock,helper.settings(),()->true),clock,()->true).run(()->true));var payload=f.f.jdbc.queryForObject("SELECT missing_inputs_json FROM jobs WHERE task_type='agent_analysis' AND record_kind='logical_task' AND state='queued'",String.class);assertTrue(payload.contains("fictional-second"));assertEquals(2,f.f.sends);}
    @Test void PreparedNativeReceiptWinsAfterCurrentBusinessTablesDisappearAndGateStopsReading(){var helper=helper();var outer=helper.outer();var f=outer.new NewFixture();f.terminal("workflow");f.completeSource();var clock=Clock.fixed(outer.completed.plusSeconds(120),ZoneOffset.UTC);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.PREPARED,cycle(f,helper.graph(f,clock,helper.settings(),()->true),clock,()->true).run(()->true));for(String table:List.of("sources","source_run_items","analyzed_entities","contents"))f.f.jdbc.execute("DROP TABLE "+table);var gate=mock(BooleanSupplier.class);var settings=mock(GenerationFlowService.SettingsSnapshotSource.class);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.SETTLED,cycle(f,helper.graph(f,clock,settings,gate),clock,gate).run(()->true));verifyNoInteractions(gate,settings);assertEquals(2,f.f.sends);}
    @Test void StoppedOuterTransactionColdConstructorAndConcurrentTickCannotStartAnotherPreparation()throws Exception{var helper=helper();var outer=helper.outer();var f=outer.new NewFixture();f.terminal("model");f.completeSource();var clock=Clock.fixed(outer.completed.plusSeconds(120),ZoneOffset.UTC);var graph=helper.graph(f,clock,helper.settings(),()->true);var cycle=cycle(f,graph,clock,()->true);int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.IDLE,cycle.run(()->false));assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.RECOVERY_REQUIRED,f.write(()->cycle.run(()->true)));assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var execution=Executors.newSingleThreadExecutor();try{var first=execution.submit(()->cycle.run(()->{entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}return false;}));assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.BUSY,cycle.run(()->true));release.countDown();assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.IDLE,first.get(5,TimeUnit.SECONDS));}finally{release.countDown();execution.shutdownNow();}assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));
        var days=mock(JdbcCatalogAnalysisDays.class);var evidence=mock(CatalogDayEntityEvidenceService.class);var eligibility=mock(CatalogDayAnalysisEligibilityService.class);var reservations=mock(CatalogDayAnalysisReservationLedger.class);var allocation=mock(CatalogDayAnalysisGenerationService.class);var originals=mock(CatalogAnalysisPreparedInputService.class);var preparation=mock(CatalogDayAnalysisPreparationService.class);var tx=mock(PlatformTransactionManager.class);var time=mock(Clock.class);var gate=mock(BooleanSupplier.class);assertNotNull(new CatalogDayAnalysisPreparationCycle(days,evidence,eligibility,reservations,allocation,originals,preparation,tx,time,gate,"agent"));verifyNoInteractions(days,evidence,eligibility,reservations,allocation,originals,preparation,tx,time,gate);
    }
}
